# The tests in `ITF1788_tests/` are generated by `generate()` from the test suite ITF1788
# (https://github.com/oheim/ITF1788) in `itl/`. Each test case `function arguments = results;`,
# possibly followed by `signal …`, becomes a test; e.g. `add [1.0, 2.0] [1.0, 2.0] = [2.0, 4.0];`
# becomes `@test +(bareinterval(1.0, 2.0), bareinterval(1.0, 2.0)) === bareinterval(2.0, 4.0)`.

"""
    generate()
    generate(filename)

Generate the Julia tests `ITF1788_tests/filename.jl` from the file `itl/filename.itl`, or
from every file of `itl/`. Return the path of the generated files.
"""
generate() = map(generate, filter(endswith(".itl"), readdir(joinpath(@__DIR__, "itl"))))
function generate(filename::AbstractString)
    testsets = String[]
    name, tests = nothing, String[]
    for line ∈ strip.(readlines(joinpath(@__DIR__, "itl", filename)))
        m = match(r"^testcase\s+(\S+)\s+\{$", line)
        if !isnothing(m)
            name, tests = m[1], String[]
        elseif line == "}"
            push!(testsets, "@testset \"$name\" begin\n" * join("\n    $t\n" for t ∈ tests) * "\nend\n")
            name = nothing
        elseif !isnothing(name) && !isempty(line) && !startswith(line, "//")
            push!(tests, test(adapt(line)))
        end
    end
    dest = joinpath(@__DIR__, "ITF1788_tests", replace(filename, ".itl" => ".jl"))
    write(dest, join(testsets, "\n"))
    return dest
end

# The test cases of `textToInterval` which expect the signal `PossiblyUndefinedOperation` are
# written for an implementation which cannot tell whether the bounds of a literal are in the
# right order. The parser computes the bounds exactly, so it can: bounds in the right order are
# accepted without a signal, and bounds in the wrong order are rejected, as Section 12.12.7 of
# the IEEE Standard 1788-2015 recommends. Any other such case is an error.
const RIGHT_ORDER = ("[1.0000000000000001, 1.0000000000000002]",)
const WRONG_ORDER = ("[1.0000000000000002,1.0000000000000001]",
                     "[10000000000000001/10000000000000000,10000000000000002/10000000000000001]",
                     "[0x1.00000000000002p0,0x1.00000000000001p0]")
function adapt(line)
    m = match(r"^([bd])-textToInterval \"(.*)\" = .* signal PossiblyUndefinedOperation;$", line)
    isnothing(m) && return line
    kind, literal = m
    literal ∈ RIGHT_ORDER && return replace(line, " signal PossiblyUndefinedOperation" => "")
    literal ∈ WRONG_ORDER || return throw(ArgumentError("unexpected test case: $line"))
    return "$kind-textToInterval \"$literal\" = $(kind == "b" ? "[empty]" : "[nai]") signal UndefinedOperation;"
end

# the functions of ITF1788 whose name differs in IntervalArithmetic
const FUNCTIONS = Dict(
    "add" => "+", "sub" => "-", "pos" => "+", "neg" => "-", "mul" => "*", "div" => "/",
    "recip" => "inv", "sqr" => "pown", "atan2" => "atan", "logp1" => "log1p",
    "roundTiesToEven" => "round", "roundTiesToAway" => "round",
    "convexHull" => "hull", "intersection" => "intersect_interval",
    "cancelPlus" => "cancelplus", "cancelMinus" => "cancelminus",
    "rad" => "radius", "midRad" => "midradius", "wid" => "diam",
    "intervalPart" => "bareinterval", "decorationPart" => "decoration",
    "newDec" => "interval", "setDec" => "interval",
    "isEmpty" => "isempty_interval", "isEntire" => "isentire_interval", "isNaI" => "isnai",
    "isCommonInterval" => "iscommon", "isSingleton" => "isthin", "isMember" => "in_interval",
    "equal" => "isequal_interval", "subset" => "issubset_interval", "interior" => "isinterior",
    "disjoint" => "isdisjoint_interval", "less" => "isweakless", "strictLess" => "isstrictless",
    "strictPrecedes" => "strictprecedes")
const EXTRA_ARGUMENT = Dict("sqr" => "2", "roundTiesToAway" => "RoundNearestTiesAway")

# e.g. `add [1.0, 2.0] [1.0, 2.0] = [2.0, 4.0];`, `inf [nai] = NaN;` or `b-numsToInterval 2 1 = [empty] signal UndefinedOperation;`
function test(line)
    fname, args, results, signal = match(r"^(\S+)\s+(.*?)\s*=\s*(.*?)(\s+signal\s+\w+)?\s*;$", line)
    name = replace(fname, r"^[bd]-" => "")
    T = startswith(fname, "d-") ? "Interval" : "BareInterval"
    if name == "textToInterval" # the argument is a string
        call = "parse($T{Float64}, $args)"
    else
        args = map(value, eachmatch(TOKEN, replace(args, "infinity" => "Inf", "X" => "x")))
        if name == "numsToInterval"
            call = "$(lowercase(T))($(join(args, ',')))"
        else
            haskey(EXTRA_ARGUMENT, name) && push!(args, EXTRA_ARGUMENT[name])
            call = "$(get(FUNCTIONS, name, name))($(join(args, ", ")))"
        end
    end
    results = map(eachmatch(TOKEN, replace(results, "infinity" => "Inf", "X" => "x"))) do m
        isnothing(m[1]) || return value(m)
        name == "overlap" && return "IntervalArithmetic.Overlap." * replace(m.match, r"[A-Z]" => c -> "_" * lowercase(c))
        return isnothing(tryparse(Int64, m.match)) ? m.match : m.match * ".0"
    end
    check(x, r) = r == "NaN" ? "isnan($x)" : "$x === $r"
    expr = length(results) == 1 ? check(call, only(results)) :
        join((check("$call[$i]", r) for (i, r) ∈ enumerate(results)), " && ")
    # a signal is a warning; the parser must not print one otherwise
    isnothing(signal) || return "@test_logs (:warn,) @test $expr"
    name == "textToInterval" && return "@test_logs @test $expr"
    return "@test $expr"
end

# an interval, possibly decorated, or any other value
const TOKEN = r"\[([^\]]*)\](?:_(\w+))?|\S+"
function value(m::RegexMatch)
    isnothing(m[1]) && return m.match
    m[1] == "nai" && return "nai(Interval{Float64})"
    x = m[1] == "empty" ? "emptyinterval(BareInterval{Float64})" :
        m[1] == "entire" ? "entireinterval(BareInterval{Float64})" : "bareinterval($(m[1]))"
    return isnothing(m[2]) ? x : "interval($x, $(m[2]))"
end
